import math

def generate_M(pattern, length):
    """Generates a number M of given length based on the pattern."""
    digits = [int(d) for d in pattern]
    M_str = "".join([str(digits[i % len(digits)]) for i in range(length)])
    return int(M_str)

def count_zeros(Q):
    """Counts the number of zero digits in the decimal expansion of Q."""
    if Q == 0:
        return 1 # Though Q should not be 0 here
    return str(Q).count('0')

# Parameters
K = 100
N_test = [23, 29, 31, 41, 53]
M_patterns = {
    "1212": "12",
    "123123": "123",
    "132132": "132",
    "2323": "23"
}

max_A_found = 49
results = {}

print(f"Starting computational refinement with proxy length K={K}")
print("-" * 40)

for N in N_test:
    max_A_for_N = 0
    N_results = {}
    print(f"Testing Divisor N = {N}...")

    for name, pattern in M_patterns.items():
        try:
            # Generate M
            M = generate_M(pattern, K)

            # Calculate Q = floor(M / N)
            Q = M // N

            # Count zeros
            A = count_zeros(Q)

            N_results[name] = A
            if A > max_A_for_N:
                max_A_for_N = A

        except OverflowError:
            # Should not happen with K=100, but good practice
            print(f"Error calculating M for N={N}, Pattern={name}")
            continue

    results[N] = {"max_A": max_A_for_N, "details": N_results}
    print(f"-> Maximum A found for N={N} is {max_A_for_N}")

print("-" * 40)
print("FINAL SUMMARY OF RESULTS:")
for N, data in results.items():
    print(f"N={N}: Max A = {data['max_A']}")
    # print(f"  Details: {data['details']}") # Uncomment for full trace
print(f"Overall maximum A found across all tests: {max(d['max_A'] for d in results.values())}")
